import { LocalStorage } from '@game-studio/utilities';
import { ISettingsOption, IUserPreferences, UserPreferenceValue } from './types';

export class UserPreferences {
    private static userId: number | string;

    private static gameName: string;

    private static userPreferences: IUserPreferences | null;

    private static globalPreferences: IUserPreferences | null;

    private static get key() {
        return `${this.gameName}-userprefs-${this.userId}`;
    }

    private static get globalKey() {
        return `global-${this.userId}`;
    }

    public static init(userId: number | string, gameName: string) {
        this.userId = userId;
        this.gameName = gameName;
        this.userPreferences = LocalStorage.getItem(this.key);
        this.globalPreferences = LocalStorage.getItem(this.globalKey);
    }

    public static getPreference<T extends UserPreferenceValue>(key: string, defaultValue: T, isMisc: boolean, isGlobal: boolean, options?: ISettingsOption[]) {
        const preferences = isGlobal ? this.globalPreferences : this.userPreferences;

        if (preferences === null) {
            return defaultValue;
        }

        const value: T = isMisc ? preferences.misc[key] as T : preferences[key] as T;

        if (value !== void 0) {
            return value;
        }

        if (!options) {
            return defaultValue;
        }

        return this.findMatch(options, defaultValue);
    }

    public static hasPreference<T extends UserPreferenceValue>(key: string, isMisc: boolean, isGlobal: boolean) {
        const preferences = isGlobal ? this.globalPreferences : this.userPreferences;

        if (preferences === null) {
            return false;
        }

        const value: T = isMisc ? preferences.misc[key] as T : preferences[key] as T;

        return value !== void 0 ? true : false;
    }

    public static getAllMisc(isGlobal: boolean) {
        const preferences = isGlobal ? this.globalPreferences : this.userPreferences;

        if (preferences === null) {
            return {};
        }

        return preferences.misc;
    }

    public static setPreference(key: string, value: UserPreferenceValue, isMisc: boolean, isGlobal: boolean, isSubGame: boolean = false) {
        let preferences = isGlobal ? this.globalPreferences : this.userPreferences;

        if (preferences === null) {
            preferences = {
                misc: {}
            };
        }

        function setValue(obj: IUserPreferences, key: string, value: UserPreferenceValue) {
            if (isMisc) {
                obj.misc[key] = value;
            } else {
                obj[key] = value;
            }
        }

        if (typeof value === 'object') {
            // Check if this is a radio button option first
            if (value.text && value.value && Object.keys(value).length === 2) {
                setValue(preferences, key, (value as ISettingsOption).value);
                // preferences[key] = (value as ISettingsOption).value;
            } else {
                setValue(preferences, key, value);
                // preferences[key] = value;
            }
        } else {
            setValue(preferences, key, value);
            // preferences[key] = value;
        }

        if (!isSubGame) {
            LocalStorage.setItem(isGlobal ? this.globalKey : this.key, preferences);
        }

        if (isGlobal) {
            this.globalPreferences = preferences;
        } else {
            this.userPreferences = preferences;
        }
    }

    private static findMatch<T extends UserPreferenceValue>(options: ISettingsOption[], defaultValue: T) {
        const match = options.find((option) => option.value === defaultValue);

        if (match) {
            return match.value as T;
        }

        return defaultValue;
    }
}